/*Table structure for table `clinic_consultations` */

DROP TABLE IF EXISTS `clinic_consultations`;

CREATE TABLE `clinic_consultations` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `student_id` int(11) DEFAULT NULL,
  `student_number` varchar(20) NOT NULL,
  `patient_name` varchar(150) NOT NULL,
  `patient_age` int(11) DEFAULT NULL,
  `patient_gender` varchar(20) DEFAULT NULL,
  `patient_course` varchar(50) DEFAULT NULL,
  `patient_year` varchar(20) DEFAULT NULL,
  `age` int(11) DEFAULT NULL,
  `gender` varchar(20) DEFAULT NULL,
  `course` varchar(50) DEFAULT NULL,
  `year_level` varchar(20) DEFAULT NULL,
  `nurse` varchar(100) NOT NULL,
  `visit_type` varchar(50) NOT NULL,
  `appointment_date` date NOT NULL,
  `appointment_time` time NOT NULL,
  `visit_date` date DEFAULT NULL,
  `visit_time` time DEFAULT NULL,
  `temperature` decimal(4,1) DEFAULT NULL,
  `blood_pressure` varchar(10) DEFAULT NULL,
  `heart_rate` int(11) DEFAULT NULL,
  `respiratory_rate` int(11) DEFAULT NULL,
  `oxygen_sat` int(11) DEFAULT NULL,
  `oxygen_saturation` int(11) DEFAULT NULL,
  `symptoms` text DEFAULT NULL,
  `diagnosis` text DEFAULT NULL,
  `treatment` text DEFAULT NULL,
  `treatment_medication` text DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `additional_notes` text DEFAULT NULL,
  `submitted_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `chief_complaint` text DEFAULT NULL,
  `physical_examination` text DEFAULT NULL,
  `assessment` text DEFAULT NULL,
  `treatment_given` text DEFAULT NULL,
  `medication_given` varchar(255) DEFAULT NULL,
  `dosage` varchar(100) DEFAULT NULL,
  `instructions` text DEFAULT NULL,
  `allergies` text DEFAULT NULL,
  `existing_conditions` text DEFAULT NULL,
  `referral_required` varchar(10) DEFAULT NULL,
  `referral_destination` varchar(150) DEFAULT NULL,
  `status` varchar(30) DEFAULT NULL,
  `section` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_student_number` (`student_number`),
  KEY `idx_appointment_date` (`appointment_date`),
  KEY `idx_submitted_at` (`submitted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

