/*Table structure for table `cm_clinic_reports` */

DROP TABLE IF EXISTS `cm_clinic_reports`;

CREATE TABLE `cm_clinic_reports` (
  `report_id` int(10) NOT NULL,
  `report_type` enum('Daily','Weekly','Monthly','Custom','Annual') DEFAULT NULL,
  `report_date` date NOT NULL,
  `start_date` date DEFAULT NULL,
  `end_date` date DEFAULT NULL,
  `report_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`report_data`)),
  `generated_by` int(11) DEFAULT NULL,
  `status` enum('Generated','Processing','Error') DEFAULT 'Generated',
  `file_path` varchar(500) DEFAULT NULL,
  `file_format` enum('PDF','Excel','HTML','JSON') DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`report_id`),
  KEY `generated_by` (`generated_by`),
  KEY `idx_report_type` (`report_type`),
  KEY `idx_report_date` (`report_date`),
  KEY `idx_status` (`status`),
  CONSTRAINT `cm_clinic_reports_ibfk_1` FOREIGN KEY (`generated_by`) REFERENCES `user_account` (`user_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_cm_clinic_reports_generated_by` FOREIGN KEY (`generated_by`) REFERENCES `user_account` (`user_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

