  `medications_prescribed` text DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `follow_up_date` date DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `created_by` int(11) DEFAULT NULL,
  PRIMARY KEY (`record_id`),
  KEY `created_by` (`created_by`),
  KEY `idx_visit_date` (`visit_date`),
  KEY `idx_patient_id` (`patient_id`),
  KEY `idx_status` (`status`),
  KEY `idx_consultation_type` (`consultation_type`),
  CONSTRAINT `cm_medical_records_ibfk_1` FOREIGN KEY (`patient_id`) REFERENCES `cm_patients` (`patient_id`) ON DELETE CASCADE,
  CONSTRAINT `cm_medical_records_ibfk_2` FOREIGN KEY (`created_by`) REFERENCES `user_account` (`user_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_cm_medical_records_created_by` FOREIGN KEY (`created_by`) REFERENCES `user_account` (`user_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

