/*Table structure for table `cm_medicine_inventory` */

DROP TABLE IF EXISTS `cm_medicine_inventory`;

CREATE TABLE `cm_medicine_inventory` (
  `medicine_id` int(10) NOT NULL AUTO_INCREMENT,
  `medicine_name` varchar(200) NOT NULL,
  `generic_name` varchar(200) DEFAULT NULL,
  `category` varchar(100) DEFAULT NULL,
  `dosage_form` enum('Tablet','Capsule','Liquid','Injection','Ointment','Other') DEFAULT NULL,
  `strength` varchar(50) DEFAULT NULL,
  `unit` varchar(50) NOT NULL DEFAULT 'pcs',
  `current_stock` int(11) DEFAULT 0,
  `reorder_level` int(11) DEFAULT 10,
  `unit_cost` decimal(8,2) DEFAULT NULL,
  `selling_price` decimal(8,2) DEFAULT NULL,
  `expiry_date` date DEFAULT NULL,
  `supplier_id` int(11) DEFAULT NULL,
  `manufacturer` varchar(200) DEFAULT NULL,
  `storage_requirements` text DEFAULT NULL,
  `status` enum('Available','Low Stock','Out of Stock','Expired','Expiring Soon','Inactive') DEFAULT 'Available',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `created_by` int(11) DEFAULT NULL,
  PRIMARY KEY (`medicine_id`),
  KEY `created_by` (`created_by`),
  KEY `idx_medicine_name` (`medicine_name`),
  KEY `idx_category` (`category`),
  KEY `idx_status` (`status`),
  KEY `idx_expiry_date` (`expiry_date`),
  KEY `fk_cm_medicine_supplier` (`supplier_id`),
  CONSTRAINT `cm_medicine_inventory_ibfk_1` FOREIGN KEY (`created_by`) REFERENCES `user_account` (`user_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_cm_medicine_inventory_created_by` FOREIGN KEY (`created_by`) REFERENCES `user_account` (`user_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_cm_medicine_inventory_supplier` FOREIGN KEY (`supplier_id`) REFERENCES `cm_suppliers` (`supplier_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_cm_medicine_inventory_supplier_id` FOREIGN KEY (`supplier_id`) REFERENCES `cm_suppliers` (`supplier_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_cm_medicine_supplier` FOREIGN KEY (`supplier_id`) REFERENCES `cm_suppliers` (`supplier_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

