  `document_type` enum('coe','quitclaim','exit_acknowledgement','leave_agreement','return_to_work_agreement','nda','training_bond','study_leave','non_compete','nte','written_warning','suspension_notice','employee_handbook','notice_of_decision','termination_decision','exit_clearance','clearance_survey') DEFAULT NULL,
  `request_status` varchar(100) DEFAULT 'draft',
  `archived` tinyint(1) DEFAULT 0,
  `signature_status` varchar(50) DEFAULT 'none',
  `requires_signature` tinyint(1) DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `required_by` date DEFAULT NULL,
  `assigned_to` int(11) DEFAULT NULL,
  `priority` varchar(50) DEFAULT 'Medium',
  `notes` varchar(50) DEFAULT 'Medium',
  `template_code` varchar(50) DEFAULT NULL,
  `document_purpose` varchar(200) DEFAULT NULL,
  `verified` tinyint(1) DEFAULT 0,
  `reminder_sent_at` datetime DEFAULT NULL,
  PRIMARY KEY (`request_id`),
  KEY `fk_em_lc_document_requests_employee_id` (`employee_id`),
  CONSTRAINT `fk_em_lc_document_requests_employee_id` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

