/*Table structure for table `enr_payment_submissions` */

DROP TABLE IF EXISTS `enr_payment_submissions`;

CREATE TABLE `enr_payment_submissions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `student_id` int(11) NOT NULL,
  `school_year_id` int(10) DEFAULT NULL,
  `semester_id` int(10) DEFAULT NULL,
  `file_data` varchar(255) DEFAULT NULL,
  `file_name` varchar(255) DEFAULT NULL,
  `file_mime` varchar(100) DEFAULT NULL,
  `status` enum('pending','verified','rejected') NOT NULL DEFAULT 'pending',
  `notes` text DEFAULT NULL,
  `submitted_at` datetime NOT NULL DEFAULT current_timestamp(),
  `verified_at` datetime DEFAULT NULL,
  `verified_by` int(11) DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_payment_student` (`student_id`),
  KEY `idx_payment_school_year` (`school_year_id`),
  KEY `idx_payment_semester` (`semester_id`),
  KEY `idx_payment_status` (`status`),
  KEY `idx_payment_submissions_deleted` (`student_id`,`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

