/*Table structure for table `enr_student_requirements` */

DROP TABLE IF EXISTS `enr_student_requirements`;

CREATE TABLE `enr_student_requirements` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `applicant_id` int(11) NOT NULL,
  `requirement_id` int(11) NOT NULL,
  `file_data` longblob DEFAULT NULL,
  `file_name` varchar(255) DEFAULT NULL,
  `custom_name` varchar(255) DEFAULT NULL,
  `file_mime` varchar(100) DEFAULT NULL,
  `is_submitted` tinyint(1) DEFAULT 0,
  `submitted_date` datetime DEFAULT NULL,
  `status` enum('pending','verified','rejected') NOT NULL DEFAULT 'pending',
  `notes` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_applicant_requirement` (`applicant_id`,`requirement_id`),
  KEY `fk_esr_requirement` (`requirement_id`),
  CONSTRAINT `fk_esr_requirement` FOREIGN KEY (`requirement_id`) REFERENCES `enr_requirements` (`requirement_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=280 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

