  KEY `idx_exit_settlement_status` (`status`),
  KEY `idx_exit_settlement_last_working_date` (`last_working_date`),
  CONSTRAINT `fk_exit_settlements_employee` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

