/*Table structure for table `exit_interviews` */

DROP TABLE IF EXISTS `exit_interviews`;

CREATE TABLE `exit_interviews` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `employee_id` int(10) NOT NULL,
  `interviewer_id` int(11) DEFAULT NULL,
  `scheduled_date` date NOT NULL,
  `scheduled_time` time NOT NULL,
  `location` varchar(255) DEFAULT 'Virtual',
  `notes` text DEFAULT NULL,
  `status` enum('scheduled','completed','cancelled') DEFAULT 'scheduled',
  `feedback` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `exit_case_type` enum('resignation','termination') DEFAULT NULL,
  `exit_case_id` int(11) DEFAULT NULL,
  `completed_at` timestamp NULL DEFAULT NULL,
  `approved_by` int(11) DEFAULT NULL,
  `approved_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_exit_interviews_employee` (`employee_id`),
  CONSTRAINT `fk_exit_interviews_employee` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `exit_interviews` */

/*Table structure for table `exit_knowledge_transfer_items` */

DROP TABLE IF EXISTS `exit_knowledge_transfer_items`;

CREATE TABLE `exit_knowledge_transfer_items` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `plan_id` int(11) NOT NULL,
  `item_type` enum('document','process','contact','system','other') NOT NULL,
  `title` varchar(255) NOT NULL,
  `description` text DEFAULT NULL,
  `priority` enum('low','medium','high') DEFAULT 'medium',
  `status` enum('pending','in_progress','completed') DEFAULT 'pending',
  `completed_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `notes` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_exit_transfer_items_plan` (`plan_id`),
  CONSTRAINT `fk_exit_transfer_items_plan` FOREIGN KEY (`plan_id`) REFERENCES `exit_knowledge_transfer_plans` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `exit_knowledge_transfer_items` */

/*Table structure for table `exit_knowledge_transfer_plans` */

DROP TABLE IF EXISTS `exit_knowledge_transfer_plans`;

CREATE TABLE `exit_knowledge_transfer_plans` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `employee_id` int(10) NOT NULL,
  `successor_id` int(10) DEFAULT NULL,
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `status` enum('active','completed','cancelled') DEFAULT 'active',
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `ld_status` varchar(50) NOT NULL DEFAULT 'not_requested',
  `ld_requested_at` datetime DEFAULT NULL,
  `ld_requested_by` int(11) DEFAULT NULL,
  `ld_last_synced_at` datetime DEFAULT NULL,
  `ld_progress_percent` int(11) NOT NULL DEFAULT 0,
  `ld_approved_by` int(11) DEFAULT NULL,
  `ld_approved_at` datetime DEFAULT NULL,
  `ld_last_sync_notes` text DEFAULT NULL,
  `ld_path_id` int(11) DEFAULT NULL,
  `ld_path_title` varchar(255) DEFAULT NULL,
  `ld_path_external_ref` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_exit_transfer_plans_employee` (`employee_id`),
  KEY `fk_exit_transfer_plans_successor` (`successor_id`),
  CONSTRAINT `fk_exit_transfer_plans_employee` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_exit_transfer_plans_successor` FOREIGN KEY (`successor_id`) REFERENCES `em_employees` (`employee_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

