/*Table structure for table `exit_survey_answers` */

DROP TABLE IF EXISTS `exit_survey_answers`;

CREATE TABLE `exit_survey_answers` (
  `id` int(11) NOT NULL,
  `response_id` int(11) NOT NULL,
  `question_id` int(11) NOT NULL,
  `answer_text` text DEFAULT NULL,
  `answer_value` varchar(255) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_exit_survey_answers_response_id_exit_survey_responses` (`response_id`),
  KEY `fk_exit_survey_answers_question_id_exit_survey_questions` (`question_id`),
  CONSTRAINT `fk_exit_survey_answers_question_id_exit_survey_questions` FOREIGN KEY (`question_id`) REFERENCES `exit_survey_questions` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_exit_survey_answers_response_id` FOREIGN KEY (`response_id`) REFERENCES `pm_feedback_responses` (`response_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_exit_survey_answers_response_id_exit_survey_responses` FOREIGN KEY (`response_id`) REFERENCES `exit_survey_responses` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `exit_survey_answers` */

/*Table structure for table `exit_survey_questions` */

DROP TABLE IF EXISTS `exit_survey_questions`;

CREATE TABLE `exit_survey_questions` (
  `id` int(11) NOT NULL,
  `survey_id` int(11) NOT NULL,
  `question_text` text NOT NULL,
  `question_type` enum('text','textarea','radio','checkbox','select','rating') NOT NULL,
  `options` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`options`)),
  `required` tinyint(1) DEFAULT 0,
  `order_num` int(11) DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `rating` tinyint(4) DEFAULT NULL,
  `rated_at` timestamp NULL DEFAULT NULL,
  `rated_by` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_exit_survey_questions_survey_id_exit_surveys` (`survey_id`),
  CONSTRAINT `fk_exit_survey_questions_survey_id_exit_surveys` FOREIGN KEY (`survey_id`) REFERENCES `exit_surveys` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

