/*Table structure for table `lbr_book_similarity` */

DROP TABLE IF EXISTS `lbr_book_similarity`;

CREATE TABLE `lbr_book_similarity` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `book_id_a` int(11) NOT NULL,
  `book_id_b` int(11) NOT NULL,
  `similarity_score` decimal(5,4) DEFAULT 0.0000,
  `computed_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_pair` (`book_id_a`,`book_id_b`),
  KEY `book_id_b` (`book_id_b`),
  KEY `idx_score` (`similarity_score`),
  CONSTRAINT `lbr_book_similarity_ibfk_1` FOREIGN KEY (`book_id_a`) REFERENCES `lbr_books` (`id`) ON DELETE CASCADE,
  CONSTRAINT `lbr_book_similarity_ibfk_2` FOREIGN KEY (`book_id_b`) REFERENCES `lbr_books` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `lbr_book_similarity` */

/*Table structure for table `lbr_books` */

DROP TABLE IF EXISTS `lbr_books`;

CREATE TABLE `lbr_books` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(255) NOT NULL,
  `author` varchar(255) NOT NULL,
  `genre` varchar(100) DEFAULT 'General Reference',
  `year` year(4) DEFAULT NULL,
  `isbn` varchar(30) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `cover_url` varchar(500) DEFAULT NULL,
  `cover_local` varchar(255) DEFAULT NULL,
  `status` enum('available','borrowed','lost','damaged') DEFAULT 'available',
  `condition` enum('Excellent','Good','Fair','Poor') DEFAULT 'Good',
  `added_date` date DEFAULT curdate(),
  `total_stock` int(11) NOT NULL DEFAULT 1,
  `available_stock` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  KEY `idx_status` (`status`),
  KEY `idx_genre` (`genre`)
) ENGINE=InnoDB AUTO_INCREMENT=101 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `lbr_books` */

