/*Table structure for table `lbr_borrow_history` */

DROP TABLE IF EXISTS `lbr_borrow_history`;

CREATE TABLE `lbr_borrow_history` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `borrower_id` int(11) NOT NULL,
  `book_id` int(11) NOT NULL,
  `genre` varchar(100) DEFAULT NULL,
  `borrow_date` date NOT NULL,
  `due_date` date NOT NULL,
  `return_date` date DEFAULT NULL,
  `days_late` int(11) DEFAULT 0,
  `was_late` tinyint(1) DEFAULT 0,
  `fine_charged` decimal(10,2) DEFAULT 0.00,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_borrower` (`borrower_id`),
  KEY `idx_book` (`book_id`),
  KEY `idx_genre` (`genre`),
  KEY `idx_was_late` (`was_late`),
  CONSTRAINT `lbr_borrow_history_ibfk_1` FOREIGN KEY (`borrower_id`) REFERENCES `lbr_borrowers` (`id`) ON DELETE CASCADE,
  CONSTRAINT `lbr_borrow_history_ibfk_2` FOREIGN KEY (`book_id`) REFERENCES `lbr_books` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

