/*Table structure for table `lbr_reminders` */

DROP TABLE IF EXISTS `lbr_reminders`;

CREATE TABLE `lbr_reminders` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `transaction_id` int(11) NOT NULL,
  `borrower_id` int(11) NOT NULL,
  `reminder_type` enum('sms','email','both') DEFAULT 'email',
  `reminder_stage` enum('3_day','1_day','overdue','final') DEFAULT '3_day',
  `risk_score` decimal(5,2) DEFAULT 0.00,
  `sent_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `status` enum('sent','failed','pending') DEFAULT 'pending',
  `message_preview` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_transaction` (`transaction_id`),
  KEY `idx_borrower` (`borrower_id`),
  KEY `idx_sent_at` (`sent_at`),
  CONSTRAINT `lbr_reminders_ibfk_1` FOREIGN KEY (`transaction_id`) REFERENCES `lbr_transactions` (`id`) ON DELETE CASCADE,
  CONSTRAINT `lbr_reminders_ibfk_2` FOREIGN KEY (`borrower_id`) REFERENCES `lbr_borrowers` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `lbr_reminders` */

