/*Table structure for table `lc_acknowledgment_log` */

DROP TABLE IF EXISTS `lc_acknowledgment_log`;

CREATE TABLE `lc_acknowledgment_log` (
  `acknowledgment_id` int(11) NOT NULL AUTO_INCREMENT,
  `employee_id` int(11) NOT NULL,
  `policy_id` int(11) DEFAULT NULL,
  `acknowledged_at` datetime DEFAULT NULL,
  `status` enum('Acknowledged','Pending','Declined') DEFAULT 'Pending',
  PRIMARY KEY (`acknowledgment_id`),
  KEY `fk_lc_ack_log_employee` (`employee_id`),
  KEY `fk_lc_acknowledgment_log_policy_id` (`policy_id`),
  CONSTRAINT `fk_lc_ack_log_employee` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_lc_ack_log_policy` FOREIGN KEY (`policy_id`) REFERENCES `lc_policies` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_lc_acknowledgment_log_policy_id` FOREIGN KEY (`policy_id`) REFERENCES `lc_policies` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

