/*Table structure for table `lc_complaint_workflow_decisions` */

DROP TABLE IF EXISTS `lc_complaint_workflow_decisions`;

CREATE TABLE `lc_complaint_workflow_decisions` (
  `id` int(11) NOT NULL,
  `complaint_id` int(11) NOT NULL,
  `workflow_step_key` varchar(100) NOT NULL,
  `workflow_step_label` varchar(255) NOT NULL,
  `decision` varchar(100) NOT NULL,
  `rationale` text DEFAULT NULL,
  `answers` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`answers`)),
  `missing_information` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`missing_information`)),
  `evidence_status` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`evidence_status`)),
  `requires_human_decision` tinyint(1) NOT NULL DEFAULT 1,
  `next_steps` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`next_steps`)),
  `decided_by` int(11) DEFAULT NULL,
  `decided_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_complaint_step_decision` (`complaint_id`,`workflow_step_key`,`decided_at`),
  KEY `idx_complaint_decided` (`complaint_id`,`decided_at`),
  CONSTRAINT `fk_complaint_workflow_decisions_complaint` FOREIGN KEY (`complaint_id`) REFERENCES `lc_complaints` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `lc_complaint_workflow_decisions` */

/*Table structure for table `lc_complaint_workflow_evidence` */

DROP TABLE IF EXISTS `lc_complaint_workflow_evidence`;

CREATE TABLE `lc_complaint_workflow_evidence` (
  `id` int(11) NOT NULL,
  `complaint_id` int(11) NOT NULL,
  `workflow_step_key` varchar(100) NOT NULL,
  `evidence_item` varchar(255) NOT NULL,
  `required` tinyint(1) NOT NULL DEFAULT 1,
  `status` enum('received','reviewed','insufficient','not_applicable','missing') NOT NULL DEFAULT 'missing',
  `notes` text DEFAULT NULL,
  `uploaded_by` int(11) DEFAULT NULL,
  `uploaded_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_complaint_step_evidence` (`complaint_id`,`workflow_step_key`,`evidence_item`),
  KEY `idx_complaint_step_evidence` (`complaint_id`,`workflow_step_key`),
  CONSTRAINT `fk_complaint_workflow_evidence_complaint` FOREIGN KEY (`complaint_id`) REFERENCES `lc_complaints` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `lc_complaint_workflow_evidence` */

/*Table structure for table `lc_complaint_workflow_questions` */

DROP TABLE IF EXISTS `lc_complaint_workflow_questions`;

CREATE TABLE `lc_complaint_workflow_questions` (
  `id` int(11) NOT NULL,
  `complaint_id` int(11) NOT NULL,
  `workflow_step_key` varchar(100) NOT NULL,
  `workflow_step_label` varchar(255) NOT NULL,
  `question` text NOT NULL,
  `purpose` text NOT NULL,
  `question_type` enum('yes_no','single_choice','multiple_choice','free_text','date','number','evidence_upload','person_selection','confirmation') NOT NULL DEFAULT 'free_text',
  `options` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`options`)),
  `required` tinyint(1) NOT NULL DEFAULT 1,
  `can_advance_after_answer` tinyint(1) NOT NULL DEFAULT 0,
  `answer` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`answer`)),
  `answered_at` datetime DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_complaint_step` (`complaint_id`,`workflow_step_key`),
  KEY `idx_complaint_created` (`complaint_id`,`created_at`),
  CONSTRAINT `fk_complaint_workflow_questions_complaint` FOREIGN KEY (`complaint_id`) REFERENCES `lc_complaints` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `lc_complaint_workflow_questions` */

/*Table structure for table `lc_complaint_workflow_reopens` */

DROP TABLE IF EXISTS `lc_complaint_workflow_reopens`;

CREATE TABLE `lc_complaint_workflow_reopens` (
  `id` int(11) NOT NULL,
  `complaint_id` int(11) NOT NULL,
  `previous_status` varchar(50) DEFAULT NULL,
  `previous_step_key` varchar(100) DEFAULT NULL,
  `reason` text DEFAULT NULL,
  `reopened_by` int(11) DEFAULT NULL,
  `reopened_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_complaint_workflow_reopens_complaint` (`complaint_id`),
  CONSTRAINT `fk_complaint_workflow_reopens_complaint` FOREIGN KEY (`complaint_id`) REFERENCES `lc_complaints` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `lc_complaint_workflow_reopens` */

/*Table structure for table `lc_complaints` */

DROP TABLE IF EXISTS `lc_complaints`;

CREATE TABLE `lc_complaints` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `type` varchar(150) DEFAULT NULL,
  `severity` varchar(20) DEFAULT 'medium',
  `status` enum('under_initial_review','under_investigation','nte_issued','pending_employee_response','for_decision','closed_no_violation','closed_warning_issued','closed_suspension','closed_termination_recommended','closed_resolved','closed','closed_second_written_warning','closed_final_written_warning','termination_employee_reply','termination_reviewed','terminated') DEFAULT 'under_initial_review',
  `employee_id` int(11) DEFAULT NULL,
  `respondent_employee_id` int(11) DEFAULT NULL,
  `reporter_name` varchar(150) DEFAULT NULL,
  `reporter_department` varchar(150) DEFAULT NULL,
  `incident_date` date DEFAULT NULL,
  `incident_time` time DEFAULT NULL,
  `location` varchar(255) DEFAULT NULL,
  `title` varchar(255) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `assigned_to` int(11) DEFAULT NULL,
  `assigned_name` varchar(150) DEFAULT NULL,
  `workflow_progress` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Interactive workflow progress' CHECK (json_valid(`workflow_progress`)),
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `employee_response` text DEFAULT NULL,
  `employee_response_date` datetime DEFAULT NULL,
  `termination_reply` text DEFAULT NULL,
  `termination_review_status` enum('pending','rejected','considered') DEFAULT 'pending',
  `termination_recommended_at` datetime DEFAULT NULL,
  `termination_loi_pdf_path` varchar(255) DEFAULT NULL,
  `termination_loi_submitted_at` datetime DEFAULT NULL,
  `officer_notes` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_complaint_workflow_progress` (`id`,`updated_at`),
  KEY `idx_respondent_employee_id` (`respondent_employee_id`)
) ENGINE=InnoDB AUTO_INCREMENT=76 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `lc_complaints` */

insert  into `lc_complaints`(`id`,`type`,`severity`,`status`,`employee_id`,`respondent_employee_id`,`reporter_name`,`reporter_department`,`incident_date`,`incident_time`,`location`,`title`,`description`,`assigned_to`,`assigned_name`,`workflow_progress`,`created_at`,`updated_at`,`employee_response`,`employee_response_date`,`termination_reply`,`termination_review_status`,`termination_recommended_at`,`termination_loi_pdf_path`,`termination_loi_submitted_at`,`officer_notes`) values 
(61,'Workplace Conduct','medium','under_initial_review',1001,1002,'Jhon Carlo Garcia',NULL,'2026-10-25',NULL,'Administration Office','Repeated Interruptions During Departmental Meetings - 20261025143837-1','A staff report describes repeated interruptions during departmental meetings and requests an HR review under the workplace conduct policy.',NULL,NULL,NULL,'2026-10-25 22:38:37','2026-10-25 22:38:37',NULL,NULL,NULL,'pending',NULL,NULL,NULL,NULL),
