/*Table structure for table `lc_document_requests` */

DROP TABLE IF EXISTS `lc_document_requests`;

CREATE TABLE `lc_document_requests` (
  `request_id` int(11) NOT NULL AUTO_INCREMENT,
  `employee_id` int(11) DEFAULT NULL,
  `rao_hired_id` int(11) DEFAULT NULL,
  `document_type` varchar(255) DEFAULT NULL,
  `request_status` varchar(100) DEFAULT 'draft',
  `archived` tinyint(1) DEFAULT 0,
  `signature_status` varchar(50) DEFAULT 'none',
  `requires_signature` tinyint(1) DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `required_by` date DEFAULT NULL,
  `assigned_to` int(11) DEFAULT NULL,
  `priority` varchar(50) DEFAULT 'Medium',
  `notes` varchar(50) DEFAULT 'Medium',
  `template_code` varchar(50) DEFAULT NULL,
  `verified` tinyint(1) DEFAULT 0,
  `reminder_sent_at` datetime DEFAULT NULL,
  PRIMARY KEY (`request_id`),
  KEY `idx_rao_hired_id` (`rao_hired_id`),
  CONSTRAINT `fk_document_request_rao_hired` FOREIGN KEY (`rao_hired_id`) REFERENCES `rao_hired` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=481 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `lc_document_requests` */

/*Table structure for table `lc_email_templates` */

DROP TABLE IF EXISTS `lc_email_templates`;

CREATE TABLE `lc_email_templates` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `template_code` varchar(100) DEFAULT NULL,
  `scenario` varchar(100) DEFAULT NULL,
  `component` enum('subject','body') NOT NULL,
  `component_order` int(11) DEFAULT 0,
  `template_text` text DEFAULT NULL,
  `status` enum('Active','Inactive') DEFAULT 'Active',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_template_code` (`template_code`),
  KEY `idx_scenario` (`scenario`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `lc_email_templates` */

insert  into `lc_email_templates`(`id`,`template_code`,`scenario`,`component`,`component_order`,`template_text`,`status`,`created_at`,`updated_at`) values 
(1,'risk_assessment_notification','risk_assessment_notification','subject',1,'Risk Assessment Notification: Workplace Accident - Critical','Active','2026-08-26 15:50:07','2026-08-26 15:50:07'),
(2,'risk_assessment_notification','risk_assessment_notification','body',2,'Dear Iris Soriano,\n\nThis is a notification regarding a risk assessment requiring your attention:\n\nRisk Category: Workplace Accident\nSeverity: Critical\nDescription: Workplace accident reported requiring immediate safety review.\nMitigation Plan: Conduct workplace inspection and implement safety measures.\n\nPlease review the details and take the necessary action at your earliest convenience. If you have any questions or need assistance, feel free to reach out to the HR department.\n\nBest regards,\nHR Department','Active','2026-08-26 15:50:07','2026-08-26 15:50:07');

/*Table structure for table `lc_employee_explanation_tokens` */

DROP TABLE IF EXISTS `lc_employee_explanation_tokens`;

CREATE TABLE `lc_employee_explanation_tokens` (
