/*Table structure for table `lc_hearing_email_log` */

DROP TABLE IF EXISTS `lc_hearing_email_log`;

CREATE TABLE `lc_hearing_email_log` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `event_id` int(11) NOT NULL,
  `notification_type` varchar(40) NOT NULL,
  `dedupe_key` varchar(191) NOT NULL,
  `recipient` varchar(190) DEFAULT NULL,
  `delivery_status` varchar(20) NOT NULL DEFAULT 'pending',
  `error_message` text DEFAULT NULL,
  `attempted_at` datetime DEFAULT NULL,
  `sent_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_hearing_email_dedupe` (`dedupe_key`),
  KEY `idx_hearing_email_event` (`event_id`),
  KEY `idx_hearing_email_status` (`delivery_status`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

