/*Table structure for table `lc_lala_question_patterns` */

DROP TABLE IF EXISTS `lc_lala_question_patterns`;

CREATE TABLE `lc_lala_question_patterns` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `pattern` varchar(500) NOT NULL,
  `normalized_pattern` varchar(500) NOT NULL,
  `intent` varchar(100) NOT NULL,
  `source` varchar(50) DEFAULT NULL,
  `matched_count` int(10) unsigned NOT NULL DEFAULT 0,
  `approved` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_normalized_pattern` (`normalized_pattern`),
  KEY `idx_intent` (`intent`),
  KEY `idx_approved` (`approved`),
  KEY `idx_matched_count` (`matched_count`)
) ENGINE=InnoDB AUTO_INCREMENT=27 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

