  `reference_no` varchar(255) DEFAULT NULL,
  `date_received` datetime DEFAULT NULL,
  `date_sent` datetime DEFAULT NULL,
  `sender` varchar(255) DEFAULT NULL,
  `recipient` varchar(255) DEFAULT NULL,
  `summary` text DEFAULT NULL,
