/*Table structure for table `lc_legal_cases` */

DROP TABLE IF EXISTS `lc_legal_cases`;

CREATE TABLE `lc_legal_cases` (
  `case_id` int(11) NOT NULL AUTO_INCREMENT,
  `case_number` varchar(50) NOT NULL,
  `case_title` varchar(255) NOT NULL,
  `case_type` varchar(100) NOT NULL,
  `specific_case_type` varchar(255) DEFAULT NULL,
  `case_source` varchar(100) NOT NULL,
  `complaint_id` int(11) DEFAULT NULL,
  `employee_id` int(11) DEFAULT NULL,
  `external_agency` varchar(100) DEFAULT NULL,
  `external_reference_no` varchar(255) DEFAULT NULL,
  `docket_no` varchar(255) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `date_received` date DEFAULT NULL,
  `date_filed` date DEFAULT NULL,
  `priority` varchar(20) DEFAULT 'Medium',
  `current_status` varchar(100) DEFAULT 'Draft',
  `current_stage` varchar(100) DEFAULT 'Case Intake',
  `assigned_to` int(11) DEFAULT NULL,
  `resolution` text DEFAULT NULL,
  `date_resolved` date DEFAULT NULL,
  `date_closed` date DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `due_date` date DEFAULT NULL,
  PRIMARY KEY (`case_id`),
  UNIQUE KEY `case_number` (`case_number`),
  KEY `idx_case_number` (`case_number`),
  KEY `idx_employee_id` (`employee_id`),
  KEY `idx_complaint_id` (`complaint_id`),
  KEY `idx_status` (`current_status`),
  KEY `idx_stage` (`current_stage`),
  KEY `idx_assigned_to` (`assigned_to`),
  KEY `idx_date_received` (`date_received`),
  KEY `idx_agency` (`external_agency`)
) ENGINE=InnoDB AUTO_INCREMENT=280 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

