/*Table structure for table `lc_policies` */

DROP TABLE IF EXISTS `lc_policies`;

CREATE TABLE `lc_policies` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `policy_code` varchar(100) DEFAULT NULL,
  `title` varchar(255) NOT NULL,
  `category_id` int(11) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `content` longtext DEFAULT NULL,
  `version` varchar(50) DEFAULT '1.0',
  `effective_date` date DEFAULT NULL,
  `acknowledgement_deadline` date DEFAULT NULL,
  `status` varchar(50) DEFAULT 'Draft',
  `requires_acknowledgement` tinyint(1) DEFAULT 0,
  `attachment_path` varchar(500) DEFAULT NULL,
  `attachment_name` varchar(255) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `approved_by` int(11) DEFAULT NULL,
  `published_at` datetime DEFAULT NULL,
  `archived_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_lc_policies_created_by` (`created_by`),
  KEY `fk_lc_policies_approved_by` (`approved_by`),
  KEY `fk_lc_policies_category_id` (`category_id`),
  CONSTRAINT `fk_lc_policies_approved_by` FOREIGN KEY (`approved_by`) REFERENCES `user_account` (`user_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_lc_policies_category` FOREIGN KEY (`category_id`) REFERENCES `lc_policy_categories` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_lc_policies_category_id` FOREIGN KEY (`category_id`) REFERENCES `lc_policy_categories` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_lc_policies_created_by` FOREIGN KEY (`created_by`) REFERENCES `user_account` (`user_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

