/*Table structure for table `lc_policy_acknowledgments` */

DROP TABLE IF EXISTS `lc_policy_acknowledgments`;

CREATE TABLE `lc_policy_acknowledgments` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `employee_id` int(11) NOT NULL,
  `policy_id` int(11) DEFAULT NULL,
  `date_acknowledged` datetime DEFAULT NULL,
  `ip_address` varchar(50) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `policy_employee` (`policy_id`,`employee_id`),
  KEY `fk_lc_policy_ack_employee` (`employee_id`),
  CONSTRAINT `fk_lc_policy_ack_employee` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_lc_policy_ack_policy` FOREIGN KEY (`policy_id`) REFERENCES `lc_policies` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_lc_policy_acknowledgments_policy_id` FOREIGN KEY (`policy_id`) REFERENCES `lc_policies` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=113 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `lc_policy_acknowledgments` */

/*Table structure for table `lc_policy_assignments` */

DROP TABLE IF EXISTS `lc_policy_assignments`;

CREATE TABLE `lc_policy_assignments` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `policy_id` int(11) NOT NULL,
  `employee_id` int(11) NOT NULL,
  `due_date` date DEFAULT NULL,
  `status` varchar(50) DEFAULT 'Pending',
  `reminder_sent_at` datetime DEFAULT NULL,
  `reminder_count` int(11) DEFAULT 0,
  `assigned_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `policy_employee` (`policy_id`,`employee_id`),
  KEY `status` (`status`),
  KEY `fk_lc_policy_assignments_employee` (`employee_id`),
  CONSTRAINT `fk_lc_policy_assignments_employee` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_lc_policy_assignments_policy` FOREIGN KEY (`policy_id`) REFERENCES `lc_policies` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_lc_policy_assignments_policy_id` FOREIGN KEY (`policy_id`) REFERENCES `lc_policies` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=627 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

