/*Table structure for table `lc_risks` */

DROP TABLE IF EXISTS `lc_risks`;

CREATE TABLE `lc_risks` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `employee_id` int(11) DEFAULT NULL,
  `risk_type` varchar(100) NOT NULL,
  `severity` enum('Low','Medium','High','Critical') NOT NULL DEFAULT 'Medium',
  `description` text DEFAULT NULL,
  `mitigation_plan` text DEFAULT NULL,
  `status` enum('new_report','under_review','mitigated','resolved','closed') DEFAULT 'new_report',
  `monitoring_status` enum('pending_review','monitoring','verified','resolved','closed') DEFAULT 'pending_review',
  `compliance_review` enum('pending_verification','verified','requires_followup') DEFAULT 'pending_verification',
  `department_progress` text DEFAULT NULL,
  `review_findings` text DEFAULT NULL,
  `review_remarks` text DEFAULT NULL,
  `review_date` datetime DEFAULT NULL,
  `reviewed_by` varchar(255) DEFAULT NULL,
  `last_reviewed` datetime DEFAULT NULL,
  `supporting_documents` text DEFAULT NULL,
  `archived` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `source_module` varchar(100) DEFAULT NULL,
  `source_record_id` varchar(100) DEFAULT NULL,
  `detection_rule` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_lc_risks_source` (`source_module`,`source_record_id`,`detection_rule`,`archived`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=398 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `lc_risks` */

insert  into `lc_risks`(`id`,`employee_id`,`risk_type`,`severity`,`description`,`mitigation_plan`,`status`,`monitoring_status`,`compliance_review`,`department_progress`,`review_findings`,`review_remarks`,`review_date`,`reviewed_by`,`last_reviewed`,`supporting_documents`,`archived`,`created_at`,`updated_at`,`source_module`,`source_record_id`,`detection_rule`) values 
