/*Table structure for table `pm_appraisals` */

DROP TABLE IF EXISTS `pm_appraisals`;

CREATE TABLE `pm_appraisals` (
  `appraisal_id` int(11) NOT NULL,
  `employee_id` int(11) NOT NULL,
  `employee_name` varchar(255) NOT NULL,
  `department` int(11) DEFAULT NULL,
  `reviewer_id` int(11) DEFAULT NULL,
  `reviewer_name` varchar(255) DEFAULT NULL,
  `status` varchar(30) DEFAULT 'Not Started',
  `overall_rating` decimal(3,2) DEFAULT NULL,
  `due_date` date DEFAULT NULL,
  `review_cycle_id` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`appraisal_id`),
  KEY `idx_appraisals_employee` (`employee_id`),
  KEY `idx_appraisals_department` (`department`),
  KEY `idx_appraisals_cycle` (`review_cycle_id`),
  KEY `idx_appraisals_status` (`status`),
  KEY `fk_appraisals_reviewer` (`reviewer_id`),
  CONSTRAINT `fk_appraisals_cycle` FOREIGN KEY (`review_cycle_id`) REFERENCES `pm_review_cycles` (`cycle_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_appraisals_employee` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_appraisals_reviewer` FOREIGN KEY (`reviewer_id`) REFERENCES `em_employees` (`employee_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_pm_appraisals_employee_id` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

