/*Table structure for table `pm_evaluations` */

DROP TABLE IF EXISTS `pm_evaluations`;

CREATE TABLE `pm_evaluations` (
  `evaluation_id` int(11) NOT NULL AUTO_INCREMENT,
  `employee_id` int(11) NOT NULL,
  `employee_name` varchar(255) NOT NULL,
  `department` varchar(150) DEFAULT NULL,
  `position` varchar(150) DEFAULT NULL,
  `evaluation_cycle` varchar(100) NOT NULL,
  `evaluation_period_start` date DEFAULT NULL,
  `evaluation_period_end` date DEFAULT NULL,
  `evaluator_id` int(11) DEFAULT NULL,
  `evaluator_name` varchar(255) DEFAULT NULL,
  `evaluation_date` date DEFAULT NULL,
  `overall_score` decimal(5,2) DEFAULT NULL,
  `overall_rating` varchar(40) DEFAULT NULL,
  `status` varchar(30) NOT NULL DEFAULT 'In Progress',
  `strengths` text DEFAULT NULL,
  `areas_for_improvement` text DEFAULT NULL,
  `recommended_training` text DEFAULT NULL,
  `final_remarks` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`evaluation_id`),
  KEY `idx_evaluations_employee` (`employee_id`),
  KEY `idx_evaluations_cycle` (`evaluation_cycle`),
  KEY `idx_evaluations_status` (`status`),
  KEY `idx_evaluations_date` (`evaluation_date`),
  KEY `fk_evaluations_evaluator` (`evaluator_id`),
  CONSTRAINT `fk_evaluations_employee` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_evaluations_evaluator` FOREIGN KEY (`evaluator_id`) REFERENCES `em_employees` (`employee_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

