/*Table structure for table `pm_feedback_360_entries` */

DROP TABLE IF EXISTS `pm_feedback_360_entries`;

CREATE TABLE `pm_feedback_360_entries` (
  `feedback_id` int(11) NOT NULL,
  `employee_id` int(11) NOT NULL,
  `reviewer_id` int(11) DEFAULT NULL,
  `reviewer_type` varchar(30) NOT NULL,
  `reviewer_name` varchar(120) NOT NULL,
  `category` varchar(80) NOT NULL,
  `rating` tinyint(3) unsigned NOT NULL,
  `comments` text DEFAULT NULL,
  `review_period` varchar(50) DEFAULT NULL,
  `department` int(11) DEFAULT NULL,
  `feedback_status` varchar(30) DEFAULT 'Pending',
  `feedback_category` varchar(80) DEFAULT NULL,
  `strengths` text DEFAULT NULL,
  `areas_for_improvement` text DEFAULT NULL,
  `recommendation` varchar(80) DEFAULT NULL,
  `is_anonymous` tinyint(1) DEFAULT 0,
  `supporting_documents` varchar(255) DEFAULT NULL,
  `hr_remarks` text DEFAULT NULL,
  `overall_rating` decimal(3,2) DEFAULT NULL,
  `competency_scores` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`feedback_id`),
  KEY `idx_feedback_360_employee` (`employee_id`),
  KEY `idx_feedback_360_review_period` (`review_period`),
  KEY `fk_feedback_360_reviewer` (`reviewer_id`),
  CONSTRAINT `fk_feedback_360_employee` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_feedback_360_reviewer` FOREIGN KEY (`reviewer_id`) REFERENCES `em_employees` (`employee_id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

