/*Table structure for table `pm_feedback_assignments` */

DROP TABLE IF EXISTS `pm_feedback_assignments`;

CREATE TABLE `pm_feedback_assignments` (
  `assignment_id` int(11) NOT NULL,
  `cycle_id` int(11) NOT NULL,
  `employee_id` int(11) NOT NULL,
  `employee_name` varchar(255) DEFAULT NULL,
  `department` int(11) DEFAULT NULL,
  `rater_type_id` int(11) DEFAULT NULL,
  `rater_type_name` varchar(100) DEFAULT NULL,
  `rater_id` int(11) NOT NULL,
  `rater_name` varchar(255) DEFAULT NULL,
  `is_anonymous` tinyint(1) DEFAULT 0,
  `status` enum('Pending','Assigned','InProgress','Submitted','Completed') DEFAULT 'Pending',
  `assigned_date` timestamp NOT NULL DEFAULT current_timestamp(),
  `submission_date` timestamp NULL DEFAULT NULL,
  `assigned_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`assignment_id`),
  KEY `idx_feedback_assignments_cycle` (`cycle_id`),
  KEY `idx_feedback_assignments_employee` (`employee_id`),
  KEY `idx_feedback_assignments_rater` (`rater_id`),
  KEY `idx_feedback_assignments_rater_type` (`rater_type_id`),
  KEY `fk_feedback_assignments_assigner` (`assigned_by`),
  CONSTRAINT `fk_feedback_assignments_assigner` FOREIGN KEY (`assigned_by`) REFERENCES `em_employees` (`employee_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_feedback_assignments_cycle` FOREIGN KEY (`cycle_id`) REFERENCES `pm_feedback_cycles` (`cycle_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_feedback_assignments_employee` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_feedback_assignments_rater` FOREIGN KEY (`rater_id`) REFERENCES `em_employees` (`employee_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_feedback_assignments_rater_type` FOREIGN KEY (`rater_type_id`) REFERENCES `pm_rater_types` (`rater_type_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_pm_feedback_assignments_employee_id` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_pm_feedback_assignments_rater_type_id` FOREIGN KEY (`rater_type_id`) REFERENCES `pm_rater_types` (`rater_type_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `pm_feedback_assignments` */

/*Table structure for table `pm_feedback_cycles` */

DROP TABLE IF EXISTS `pm_feedback_cycles`;

CREATE TABLE `pm_feedback_cycles` (
  `cycle_id` int(11) NOT NULL,
  `cycle_name` varchar(255) NOT NULL,
  `cycle_period` varchar(100) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `start_date` date DEFAULT NULL,
  `end_date` date DEFAULT NULL,
  `submission_start_date` date DEFAULT NULL,
  `submission_end_date` date DEFAULT NULL,
  `status` enum('Draft','Active','Closed','Archived') DEFAULT 'Draft',
  `is_active` tinyint(1) DEFAULT 0,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`cycle_id`),
  KEY `idx_feedback_cycles_status` (`status`),
  KEY `idx_feedback_cycles_active` (`is_active`),
  KEY `idx_feedback_cycles_dates` (`start_date`,`end_date`),
  KEY `fk_feedback_cycles_creator` (`created_by`),
  CONSTRAINT `fk_feedback_cycles_creator` FOREIGN KEY (`created_by`) REFERENCES `em_employees` (`employee_id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `pm_feedback_cycles` */

/*Table structure for table `pm_feedback_history` */

DROP TABLE IF EXISTS `pm_feedback_history`;

CREATE TABLE `pm_feedback_history` (
  `history_id` int(11) NOT NULL,
  `assignment_id` int(11) DEFAULT NULL,
