  `action` varchar(100) NOT NULL,
  `action_details` text DEFAULT NULL,
  `performed_by` int(11) DEFAULT NULL,
  `performed_by_name` varchar(255) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`history_id`),
  KEY `idx_feedback_history_assignment` (`assignment_id`),
  KEY `idx_feedback_history_summary` (`summary_id`),
  KEY `idx_feedback_history_action` (`action`),
  KEY `fk_feedback_history_employee` (`performed_by`),
  CONSTRAINT `fk_feedback_history_assignment` FOREIGN KEY (`assignment_id`) REFERENCES `pm_feedback_assignments` (`assignment_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_feedback_history_employee` FOREIGN KEY (`performed_by`) REFERENCES `em_employees` (`employee_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_feedback_history_summary` FOREIGN KEY (`summary_id`) REFERENCES `pm_feedback_summary` (`summary_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_pm_feedback_history_summary_id` FOREIGN KEY (`summary_id`) REFERENCES `pm_feedback_summary` (`summary_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

