  `goal_completion_rate` decimal(5,2) DEFAULT NULL,
  `performance_status` varchar(50) DEFAULT NULL,
  `risk_level` varchar(50) DEFAULT NULL,
  `training_recommendation` varchar(255) DEFAULT NULL,
  `summary` text DEFAULT NULL,
  `status` enum('Draft','Finalized','Archived') DEFAULT 'Draft',
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`report_id`),
  UNIQUE KEY `report_code` (`report_code`),
  KEY `idx_performance_reports_employee` (`employee_id`),
  KEY `idx_performance_reports_department` (`department`),
  KEY `idx_performance_reports_period` (`review_period`),
  KEY `idx_performance_reports_status` (`status`),
  KEY `fk_performance_reports_supervisor` (`supervisor_id`),
  KEY `fk_performance_reports_creator` (`created_by`),
  CONSTRAINT `fk_performance_reports_creator` FOREIGN KEY (`created_by`) REFERENCES `em_employees` (`employee_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_performance_reports_employee` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_performance_reports_supervisor` FOREIGN KEY (`supervisor_id`) REFERENCES `em_employees` (`employee_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_pm_performance_reports_employee_id` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

