/*Table structure for table `pr_employee_benefits` */

DROP TABLE IF EXISTS `pr_employee_benefits`;

CREATE TABLE `pr_employee_benefits` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `employee_id` int(11) NOT NULL,
  `has_sss` tinyint(1) DEFAULT 1 COMMENT 'SSS Contribution enrollment',
  `has_philhealth` tinyint(1) DEFAULT 1 COMMENT 'PhilHealth enrollment',
  `has_pagibig` tinyint(1) DEFAULT 1 COMMENT 'Pag-IBIG enrollment',
  `sss_amount_override` decimal(10,2) DEFAULT NULL COMMENT 'Manual override if needed',
  `philhealth_amount_override` decimal(10,2) DEFAULT NULL,
  `pagibig_amount_override` decimal(10,2) DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_employee_benefits` (`employee_id`),
  CONSTRAINT `fk_employee_benefits` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `pr_employee_benefits` */

/*Table structure for table `pr_employee_deductions` */

DROP TABLE IF EXISTS `pr_employee_deductions`;

CREATE TABLE `pr_employee_deductions` (
  `employee_deduction_id` int(11) NOT NULL,
  `employee_id` int(11) DEFAULT NULL,
  `deduction_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`employee_deduction_id`),
  KEY `fk_employee_deductions` (`employee_id`),
  KEY `fk_employee_deductions_deduction` (`deduction_id`),
  CONSTRAINT `fk_employee_deductions` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_employee_deductions_deduction` FOREIGN KEY (`deduction_id`) REFERENCES `pr_deductions` (`deduction_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_pr_employee_deductions_deduction_id` FOREIGN KEY (`deduction_id`) REFERENCES `pr_deductions` (`deduction_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

