/*Table structure for table `pr_final_settlement_items` */

DROP TABLE IF EXISTS `pr_final_settlement_items`;

CREATE TABLE `pr_final_settlement_items` (
  `item_id` int(11) NOT NULL,
  `settlement_id` int(11) NOT NULL,
  `item_type` enum('earning','deduction') NOT NULL,
  `item_category` varchar(50) NOT NULL,
  `item_code` varchar(50) DEFAULT NULL,
  `description` varchar(255) NOT NULL,
  `amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `source_type` varchar(50) DEFAULT NULL,
  `source_id` int(11) DEFAULT NULL,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`item_id`),
  KEY `idx_final_settlement_items_settlement` (`settlement_id`),
  KEY `idx_final_settlement_items_type` (`item_type`),
  KEY `idx_final_settlement_items_category` (`item_category`),
  KEY `idx_final_settlement_items_source` (`source_type`,`source_id`),
  CONSTRAINT `fk_pr_final_settlement_items_settlement` FOREIGN KEY (`settlement_id`) REFERENCES `pr_final_settlements` (`settlement_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

