/*Table structure for table `rao_applications` */

DROP TABLE IF EXISTS `rao_applications`;

CREATE TABLE `rao_applications` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `job_id` int(11) NOT NULL,
  `first_name` varchar(100) DEFAULT NULL,
  `middle_name` varchar(100) NOT NULL,
  `last_name` varchar(100) DEFAULT NULL,
  `email` varchar(150) DEFAULT NULL,
  `phone` varchar(50) DEFAULT NULL,
  `gender` varchar(200) DEFAULT NULL,
  `birthplace` varchar(100) DEFAULT NULL,
  `birthdate` varchar(100) DEFAULT NULL,
  `age` int(200) DEFAULT NULL,
  `civil_status` varchar(200) DEFAULT NULL,
  `citizenship` varchar(200) DEFAULT NULL,
  `religion` varchar(200) DEFAULT NULL,
  `address` varchar(255) DEFAULT NULL,
  `current_address` varchar(200) DEFAULT NULL,
  `permanent_address` varchar(200) DEFAULT NULL,
  `summary` text DEFAULT NULL,
  `cover_letter` text DEFAULT NULL,
  `resume` varchar(255) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `status` varchar(20) DEFAULT 'pending',
  `hired` tinyint(1) DEFAULT 0,
  `is_archived` tinyint(1) DEFAULT 0,
  `archived_at` datetime DEFAULT NULL,
  `source` varchar(50) DEFAULT 'Online Posting',
  `ready_for_offer` tinyint(1) DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `fk_application_job` (`job_id`),
  CONSTRAINT `fk_application_job` FOREIGN KEY (`job_id`) REFERENCES `rao_jobs` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

