/*Table structure for table `rao_hired` */

DROP TABLE IF EXISTS `rao_hired`;

CREATE TABLE `rao_hired` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `application_id` int(11) NOT NULL,
  `position_id` int(11) NOT NULL,
  `department_id` int(11) NOT NULL,
  `first_name` varchar(100) DEFAULT NULL,
  `middle_name` varchar(100) NOT NULL,
  `last_name` varchar(100) DEFAULT NULL,
  `email` varchar(150) NOT NULL,
  `phone` varchar(50) NOT NULL,
  `address` varchar(255) NOT NULL,
  `position` varchar(255) DEFAULT NULL,
  `department` varchar(100) NOT NULL,
  `base_job` varchar(255) DEFAULT NULL,
  `salary` decimal(10,2) DEFAULT NULL,
  `hired_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_hired_application_id` (`application_id`),
  KEY `idx_hired_position_id` (`position_id`),
  KEY `idx_hired_department_id` (`department_id`),
  CONSTRAINT `fk_hired_application` FOREIGN KEY (`application_id`) REFERENCES `rao_applications` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_hired_department` FOREIGN KEY (`department_id`) REFERENCES `em_departments` (`department_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_rao_hired_position` FOREIGN KEY (`position_id`) REFERENCES `em_positions` (`position_id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

