/*Table structure for table `rao_jobs` */

DROP TABLE IF EXISTS `rao_jobs`;

CREATE TABLE `rao_jobs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(100) DEFAULT NULL,
  `position_id` int(11) NOT NULL,
  `department_id` int(11) NOT NULL,
  `description` text DEFAULT NULL,
  `qualifications` text DEFAULT NULL,
  `category` varchar(255) NOT NULL DEFAULT '',
  `location` enum('Bestlink Main Campus','Bestlink MV Campus','Bestlink Bulacan Campus') NOT NULL,
  `max_applicants` int(11) DEFAULT 0,
  `is_posted` tinyint(1) NOT NULL DEFAULT 0,
  `position` varchar(150) DEFAULT NULL,
  `department` varchar(150) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_job_position` (`position_id`),
  KEY `fk_job_department` (`department_id`),
  CONSTRAINT `fk_job_department` FOREIGN KEY (`department_id`) REFERENCES `em_departments` (`department_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_job_position` FOREIGN KEY (`position_id`) REFERENCES `em_positions` (`position_id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `rao_jobs` */

insert  into `rao_jobs`(`id`,`title`,`position_id`,`department_id`,`description`,`qualifications`,`category`,`location`,`max_applicants`,`is_posted`,`position`,`department`) values 
(2,'Recruitment for Staff',4,1,'Responsible for planning and delivering effective lessons, assessing student learning, managing classroom activities, and providing guidance and support to students. The teacher will prepare instructional materials, maintain accurate student records, communicate with parents and school administrators, participate in school activities, and contribute to the continuous improvement of academic programs.','Bachelorâ€™s Degree in Education or a related field.\r\nMust have a valid Professional Teacher License (if required for the position).\r\nPreferably with teaching experience in a school or educational institution.\r\nStrong classroom management and communication skills.\r\nKnowledgeable in lesson planning, curriculum implementation, and student assessment.\r\nProficient in using Microsoft Office, Google Workspace, and other educational technologies.\r\nAble to work effectively with students, parents, faculty, and administrators.\r\nResponsible, patient, organized, and committed to student development.','Teaching','Bestlink Bulacan Campus',30,1,'Instructor','It Department'),
(3,'Recruitment for Teacher',22,3,'Responsible for planning and delivering effective lessons, assessing student learning, managing classroom activities, and providing guidance and support to students. The teacher will prepare instructional materials, maintain accurate student records, communicate with parents and school administrators, participate in school activities, and contribute to the continuous improvement of academic programs.','Bachelorâ€™s Degree in Education or a related field.\r\nMust have a valid Professional Teacher License (if required for the position).\r\nPreferably with teaching experience in a school or educational institution.\r\nStrong classroom management and communication skills.\r\nKnowledgeable in lesson planning, curriculum implementation, and student assessment.\r\nProficient in using Microsoft Office, Google Workspace, and other educational technologies.\r\nAble to work effectively with students, parents, faculty, and administrators.\r\nResponsible, patient, organized, and committed to student development.','Teaching','Bestlink Main Campus',50,1,'Instructor','It Department');

