/*Table structure for table `rao_parsed_resume` */

DROP TABLE IF EXISTS `rao_parsed_resume`;

CREATE TABLE `rao_parsed_resume` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `application_id` int(11) DEFAULT NULL,
  `first_name` varchar(100) DEFAULT NULL,
  `last_name` varchar(100) DEFAULT NULL,
  `email` varchar(150) DEFAULT NULL,
  `phone` varchar(50) DEFAULT NULL,
  `job_title` varchar(150) DEFAULT NULL,
  `resume` text DEFAULT NULL,
  `approved_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_application` (`application_id`),
  CONSTRAINT `fk_application` FOREIGN KEY (`application_id`) REFERENCES `rao_applications` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

