/*Table structure for table `sd_announcements` */

DROP TABLE IF EXISTS `sd_announcements`;

CREATE TABLE `sd_announcements` (
  `announcement_id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(255) DEFAULT NULL,
  `message` text DEFAULT NULL,
  `announcement_type` enum('General Announcement','Official Memorandum','Urgent Notice','Administrative Advisory','Academic Announcement','Event Announcement') NOT NULL DEFAULT 'General Announcement',
  `priority` enum('Normal','Important','Urgent') NOT NULL DEFAULT 'Normal',
  `status` enum('Draft','Scheduled','Published','Archived','Withdrawn') NOT NULL DEFAULT 'Published',
  `audience_scope` enum('Campus','Targeted') NOT NULL DEFAULT 'Campus',
  `issuing_department_id` int(11) DEFAULT NULL,
  `publish_date` datetime DEFAULT NULL,
  `published_at` datetime DEFAULT NULL,
  `expires_at` datetime DEFAULT NULL,
  `image_file` varchar(255) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `is_archived` tinyint(1) NOT NULL DEFAULT 0,
  `archived_at` datetime DEFAULT NULL,
  `archived_by` int(11) DEFAULT NULL,
  `withdrawn_at` datetime DEFAULT NULL,
  `withdrawn_by` int(11) DEFAULT NULL,
  `withdraw_reason` varchar(255) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`announcement_id`),
  KEY `created_by` (`created_by`),
  KEY `idx_sd_announcements_archived` (`is_archived`,`archived_at`),
  KEY `fk_sd_announcements_archived_by` (`archived_by`),
  KEY `idx_sd_ann_status_publish` (`status`,`publish_date`),
  KEY `idx_sd_ann_expires` (`expires_at`),
  KEY `idx_sd_ann_issuing_dept` (`issuing_department_id`),
  KEY `idx_sd_ann_withdrawn_by` (`withdrawn_by`),
  CONSTRAINT `fk_sd_ann_issuing_dept` FOREIGN KEY (`issuing_department_id`) REFERENCES `em_departments` (`department_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_sd_ann_withdrawn_by` FOREIGN KEY (`withdrawn_by`) REFERENCES `em_employees` (`employee_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_sd_announcements_archived_by` FOREIGN KEY (`archived_by`) REFERENCES `em_employees` (`employee_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `sd_announcements_ibfk_2` FOREIGN KEY (`created_by`) REFERENCES `em_employees` (`employee_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `sd_announcements` */

/*Table structure for table `sd_approvals` */

DROP TABLE IF EXISTS `sd_approvals`;

CREATE TABLE `sd_approvals` (
  `approval_id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(255) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `justification` text DEFAULT NULL,
  `status` enum('draft','submitted','reviewed','approved','rejected') NOT NULL DEFAULT 'draft',
  `remarks` text DEFAULT NULL,
  `submitted_on` datetime DEFAULT NULL,
  `submit_by` int(10) DEFAULT NULL,
  `reviewed_by` int(10) DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  `review_notes` text DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `department` int(11) DEFAULT NULL,
  `approver_id` int(10) DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `decision` varchar(20) DEFAULT NULL,
  `file_path` varchar(255) DEFAULT NULL,
  `file_name` varchar(255) DEFAULT NULL,
  `file_size` int(10) unsigned DEFAULT NULL,
  `pdf_path` varchar(255) DEFAULT NULL,
  `ai_summary` text DEFAULT NULL,
  PRIMARY KEY (`approval_id`),
  KEY `approver_id` (`approver_id`),
  KEY `department` (`department`),
  KEY `submit_by` (`submit_by`),
  KEY `fk_sd_approvals_reviewed_by` (`reviewed_by`),
  CONSTRAINT `fk_sd_approvals_reviewed_by` FOREIGN KEY (`reviewed_by`) REFERENCES `em_employees` (`employee_id`) ON DELETE SET NULL,
  CONSTRAINT `sd_approvals_ibfk_1` FOREIGN KEY (`approver_id`) REFERENCES `em_employees` (`employee_id`),
  CONSTRAINT `sd_approvals_ibfk_2` FOREIGN KEY (`department`) REFERENCES `em_departments` (`department_id`),
  CONSTRAINT `sd_approvals_ibfk_3` FOREIGN KEY (`submit_by`) REFERENCES `em_employees` (`employee_id`)
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

