/*Table structure for table `sd_central_files` */

DROP TABLE IF EXISTS `sd_central_files`;

CREATE TABLE `sd_central_files` (
  `file_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `file_uuid` char(36) NOT NULL,
  `module_type` enum('approval','report','concern') NOT NULL,
  `record_id` int(11) NOT NULL COMMENT 'approval_id / report_id / issue_id depending on module_type',
  `original_name` varchar(255) NOT NULL,
  `stored_name` char(37) NOT NULL COMMENT '32 hex + dot + extension',
  `storage_path` varchar(255) NOT NULL COMMENT 'relative to the FTP base_dir, e.g. approvals/<hex>.pdf',
  `mime_type` varchar(127) NOT NULL,
  `file_size` int(10) unsigned NOT NULL,
  `uploaded_by` int(11) NOT NULL COMMENT 'em_employees.employee_id',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`file_id`),
  UNIQUE KEY `uq_scf_uuid` (`file_uuid`),
  UNIQUE KEY `uq_scf_storage_path` (`storage_path`),
  KEY `idx_scf_record` (`module_type`,`record_id`,`deleted_at`),
  KEY `idx_scf_uploaded_by` (`uploaded_by`),
  CONSTRAINT `fk_scf_uploader` FOREIGN KEY (`uploaded_by`) REFERENCES `em_employees` (`employee_id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `sd_central_files` */

/*Table structure for table `sd_issues` */

DROP TABLE IF EXISTS `sd_issues`;

CREATE TABLE `sd_issues` (
  `issue_id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(255) NOT NULL,
  `details` text NOT NULL,
  `desired_resolution` text DEFAULT NULL,
  `department` int(11) NOT NULL,
  `submitted_by` int(10) NOT NULL,
  `reviewed_by` int(10) DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  `review_notes` text DEFAULT NULL,
  `resolved_by` int(10) DEFAULT NULL,
  `resolved_at` datetime DEFAULT NULL,
  `resolution_notes` text DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `submitted_on` datetime DEFAULT NULL,
  `status` enum('draft','submitted','reviewed','resolved','dismissed') NOT NULL DEFAULT 'draft',
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  `file_path` varchar(255) DEFAULT NULL,
  `file_name` varchar(255) DEFAULT NULL,
  `file_size` int(10) unsigned DEFAULT NULL,
  `pdf_path` varchar(255) DEFAULT NULL,
  `ai_summary` text DEFAULT NULL,
  PRIMARY KEY (`issue_id`),
  KEY `submitted_by` (`submitted_by`),
  KEY `department` (`department`),
  KEY `fk_sd_issues_reviewed_by` (`reviewed_by`),
  KEY `fk_sd_issues_resolved_by` (`resolved_by`),
  CONSTRAINT `fk_sd_issues_resolved_by` FOREIGN KEY (`resolved_by`) REFERENCES `em_employees` (`employee_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_sd_issues_reviewed_by` FOREIGN KEY (`reviewed_by`) REFERENCES `em_employees` (`employee_id`) ON DELETE SET NULL,
  CONSTRAINT `sd_issues_ibfk_1` FOREIGN KEY (`submitted_by`) REFERENCES `em_employees` (`employee_id`),
  CONSTRAINT `sd_issues_ibfk_2` FOREIGN KEY (`department`) REFERENCES `em_departments` (`department_id`)
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

