  CONSTRAINT `sd_reports_ibfk_3` FOREIGN KEY (`report_type`) REFERENCES `sd_report_type` (`type_id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

