/*Table structure for table `ta_employee_shifts` */

DROP TABLE IF EXISTS `ta_employee_shifts`;

CREATE TABLE `ta_employee_shifts` (
  `employee_shift_id` int(11) NOT NULL AUTO_INCREMENT,
  `employee_id` int(11) NOT NULL,
  `shift_id` int(11) NOT NULL,
  `effective_from` date NOT NULL,
  `effective_to` date DEFAULT NULL,
  `start_time` time DEFAULT NULL,
  `end_time` time DEFAULT NULL,
  `break_start` time DEFAULT NULL,
  `break_end` time DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `weekday` tinyint(4) GENERATED ALWAYS AS (dayofweek(`effective_from`) - 1) VIRTUAL,
  `assigned_days` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`employee_shift_id`),
  KEY `fk_ta_employee_shifts_employee` (`employee_id`),
  KEY `fk_ta_employee_shifts_shift` (`shift_id`),
  CONSTRAINT `fk_ta_employee_shifts_employee` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_ta_employee_shifts_shift` FOREIGN KEY (`shift_id`) REFERENCES `ta_shifts` (`shift_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_ta_employee_shifts_shift_id` FOREIGN KEY (`shift_id`) REFERENCES `ta_shifts` (`shift_id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=112 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

