/*Table structure for table `ta_leave_balances` */

DROP TABLE IF EXISTS `ta_leave_balances`;

CREATE TABLE `ta_leave_balances` (
  `leave_balance_id` int(11) NOT NULL AUTO_INCREMENT,
  `employee_id` int(11) NOT NULL,
  `leave_type_id` int(11) NOT NULL,
  `year` int(11) NOT NULL,
  `opening_balance` decimal(5,2) DEFAULT 0.00,
  `used_balance` decimal(5,2) DEFAULT 0.00,
  `remaining_balance` decimal(5,2) DEFAULT 0.00,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `last_monthly_accrual_month` varchar(7) DEFAULT NULL,
  `last_yearly_allocation_year` varchar(4) DEFAULT NULL,
  PRIMARY KEY (`leave_balance_id`),
  KEY `fk_ta_leave_balances_employee` (`employee_id`),
  KEY `fk_ta_leave_balances_leave_type` (`leave_type_id`),
  CONSTRAINT `fk_ta_leave_balances_employee` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_ta_leave_balances_leave_type` FOREIGN KEY (`leave_type_id`) REFERENCES `ta_leave_types` (`leave_type_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_ta_leave_balances_leave_type_id` FOREIGN KEY (`leave_type_id`) REFERENCES `ta_leave_types` (`leave_type_id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=211 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

