/*Table structure for table `wfa_age_distribution` */

DROP TABLE IF EXISTS `wfa_age_distribution`;

CREATE TABLE `wfa_age_distribution` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `metric_date` date NOT NULL,
  `age_group` varchar(50) NOT NULL COMMENT '18-25, 26-35, 36-45, 46-55, 56+',
  `employee_count` int(11) DEFAULT 0,
  `percentage` decimal(5,2) DEFAULT 0.00,
  `average_salary` decimal(12,2) DEFAULT 0.00,
  `average_performance_score` decimal(5,2) DEFAULT 0.00,
  `department_breakdown` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`department_breakdown`)),
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_age_distribution` (`metric_date`,`age_group`),
  KEY `idx_metric_date` (`metric_date`),
  KEY `idx_age_group` (`age_group`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `wfa_age_distribution` */

/*Table structure for table `wfa_at_risk_employees_summary` */

DROP TABLE IF EXISTS `wfa_at_risk_employees_summary`;

CREATE TABLE `wfa_at_risk_employees_summary` (
  `risk_level` enum('high','medium','low') DEFAULT NULL,
  `count` bigint(21) DEFAULT NULL,
  `avg_risk_score` decimal(6,2) DEFAULT NULL,
  `percentage` decimal(26,2) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `wfa_at_risk_employees_summary` */

/*Table structure for table `wfa_attrition_tracking` */

DROP TABLE IF EXISTS `wfa_attrition_tracking`;

CREATE TABLE `wfa_attrition_tracking` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `employee_id` int(10) DEFAULT NULL,
  `separation_date` date NOT NULL,
  `separation_type` enum('resigned','retired','terminated','other') DEFAULT 'resigned',
  `department_id` int(10) DEFAULT NULL,
  `tenure_years` decimal(5,2) DEFAULT NULL,
  `reason_for_leaving` text DEFAULT NULL,
  `exit_interview_completed` tinyint(1) DEFAULT 0,
  `rehire_eligible` tinyint(1) DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_separation_date` (`separation_date`),
  KEY `idx_separation_type` (`separation_type`),
  KEY `idx_employee_id` (`employee_id`),
  KEY `fk_wfa_attrition_department` (`department_id`),
  CONSTRAINT `fk_wfa_attrition_department` FOREIGN KEY (`department_id`) REFERENCES `em_departments` (`department_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `wfa_attrition_tracking_ibfk_1` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `wfa_attrition_tracking` */

/*Table structure for table `wfa_audit_log` */

DROP TABLE IF EXISTS `wfa_audit_log`;

CREATE TABLE `wfa_audit_log` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) DEFAULT NULL,
  `action` varchar(100) NOT NULL COMMENT 'view_report, generate_report, export_data, update_filter',
  `resource_type` varchar(50) DEFAULT NULL COMMENT 'report, filter, metric',
  `resource_id` int(11) DEFAULT NULL,
  `details` text DEFAULT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_action` (`action`),
  KEY `idx_created_at` (`created_at`),
  CONSTRAINT `fk_wfa_audit_user` FOREIGN KEY (`user_id`) REFERENCES `user_account` (`user_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `wfa_audit_log` */

/*Table structure for table `wfa_compensation_analysis` */

DROP TABLE IF EXISTS `wfa_compensation_analysis`;

CREATE TABLE `wfa_compensation_analysis` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `department_id` int(10) NOT NULL,
  `position_id` int(10) NOT NULL,
  `current_avg_salary` decimal(12,2) DEFAULT 0.00,
  `market_median_salary` decimal(12,2) DEFAULT 0.00,
  `salary_competitiveness_ratio` decimal(5,2) DEFAULT NULL COMMENT 'Current/Market %',
  `employee_count` int(11) DEFAULT 0,
  `salary_range_min` decimal(12,2) DEFAULT NULL,
  `salary_range_max` decimal(12,2) DEFAULT NULL,
  `recommended_adjustment` decimal(12,2) DEFAULT NULL,
  `last_market_review` date DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_compensation` (`department_id`,`position_id`),
  KEY `idx_department` (`department_id`),
  KEY `idx_position` (`position_id`),
  CONSTRAINT `fk_wfa_comp_department` FOREIGN KEY (`department_id`) REFERENCES `em_departments` (`department_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_wfa_comp_position` FOREIGN KEY (`position_id`) REFERENCES `em_positions` (`position_id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `wfa_compensation_analysis` */

