  `vacancy_count` int(11) DEFAULT 0,
  `average_tenure_years` decimal(5,2) DEFAULT 0.00,
  `metric_date` date NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_dept_date` (`department_id`,`metric_date`),
  KEY `idx_department` (`department_id`),
  KEY `idx_metric_date` (`metric_date`),
  CONSTRAINT `fk_wfa_dept_analytics_department` FOREIGN KEY (`department_id`) REFERENCES `em_departments` (`department_id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `wfa_department_analytics` */

